import zipfile, html
from pathlib import Path
out=Path('Client_GPT_Production_Deployment_Checklist.docx')
items=[('title','Client GPT Backend and Real Time Data Integration Request'),('subtitle','Copy this request into the client GPT with the backend repositories'),('h1','Context'),('p','We are rebuilding the Redline frontend independently from the supplied Frye source code. We are not using the client GitHub or Render runtime. The repositories are source references. Explain how to reproduce the real time pipeline and deploy it under our own infrastructure.'),('h1','Inspect and explain'),('li','Identify the authoritative process for every API: root server, core server, streamer and scheduled workers.'),('li','Trace one market event from provider ingestion through normalization, engine calculation, snapshot storage, API response and frontend display.'),('li','Separate confirmed code behavior, deployed behavior, mocked behavior, disabled behavior and assumptions.'),('h1','Real time data questions'),('li','Which Massive/Polygon plan, symbols, asset classes, WebSockets and rate limits are required?'),('li','Which service receives stock and futures streams, and which REST endpoints recover historical OHLC?'),('li','Which jobs run at 5m, 10m, 30m, hourly, 4H and EOD intervals?'),('li','Where are normalized bars, engine snapshots and archives stored?'),('li','How are stale, delayed, missing, malformed and disconnected feeds handled?'),('li','Does the frontend use polling, SSE, WebSocket or a combination?'),('h1','API contract questions'),('li','Return every route with method, path, parameters, authentication, response schema, error schema and freshness fields.'),('li','Identify canonical routes for snapshot, market meter, OHLC, sectors, waves, Fibonacci, strategies, permission, sizing, journal, alerts, positions, orders and executions.'),('li','Explain all 404, 401, 403, 429, 500 and 503 responses, especially SNAPSHOT_NOT_READY.'),('h1','Engine questions'),('li','Document Engine 22 seven degrees, lifecycle, direction, Fibonacci and touched levels.'),('li','Document Engine 25 breadth, participation, sectors, macro, news and freshness.'),('li','Document Engines 26 and 29 location, tactical state and blockers.'),('li','Document the Strategy 1 chain: Engines 3, 4, 6, 7 and 9.'),('li','State which values the frontend must display exactly and which it must never reconstruct.'),('h1','Trading and journal questions'),('li','Confirm paper/live status, seven account mappings, order permissions, safety stops and reconciliation.'),('li','Document Engine 10 tradeId, contractId, partial closes, open/closed state and realized-only P&L.'),('h1','Independent deployment questions'),('li','Explain how to run core API, streamer and scheduler on new infrastructure.'),('li','Provide ports, health checks, CORS, persistent storage, worker commands and deployment order.'),('li','List provider configuration variable names without returning secret values.'),('h1','Backend secret inventory'),('p','The backend deployment must define these variable names in its private secret manager. Do not place the values in this document, the frontend bundle, GitHub source, browser storage or chat: POLYGON_API_KEY, FMP_API_KEY, FINNHUB_API_KEY, FINLIGHT_API_KEY, FRED_API_KEY, OPENAI_API_KEY, SCHWAB_APP_KEY, SCHWAB_APP_SECRET, SCHWAB_TOKEN_ENCRYPTION_KEY, PUSHOVER_APP_TOKEN, PUSHOVER_USER_KEY and GITHUB_TOKEN.'),('h1','Production readiness request'),('li','Create separate development, staging and production environments.'),('li','Run the core API, market streamer and scheduled workers as independent services.'),('li','Set CORS only for our frontend domains.'),('li','Add health checks, logs, retries, stale-data states, persistent snapshot storage and rollback.'),('li','Keep Schwab paper mode enabled until live authorization and owner approval are complete.'),('h1','New frontend requirements'),('li','Connect every page to canonical backend responses instead of fixture values.'),('li','Implement Overview, Market Meter, Index and Sectors, Chart, Waves, Strategies, Journal, Accounts, Alerts, Replay and Controls.'),('li','Show source timestamp, freshness, LIVE, PAPER, DEMO, STALE, UNAVAILABLE and ERROR states.'),('li','Use equity OHLC for stock symbols and futures OHLC for ES/MES.'),('li','Render seven Elliott degrees, Fibonacci targets, touched levels, invalidation and engine blockers.'),('li','Preserve backend decisions; never infer permission from colors or reconstruct signals in the browser.'),('li','Add responsive desktop, tablet and mobile layouts with no horizontal overflow.'),('h1','Backend production requirements'),('li','Run core API, market streamer and scheduled workers as separate managed services.'),('li','Provide persistent storage for snapshots, archives, replay data and the contract-level journal.'),('li','Add provider retry, WebSocket reconnect, rate-limit handling and stale-data detection.'),('li','Add authentication, strict CORS, health checks, logs, metrics and deployment rollback.'),('li','Expose canonical routes for market data, engines, strategies, broker state, journal and alerts.'),('li','Keep broker integration separate from market-data integration; market status can run without Schwab.'),('li','Keep paper mode enabled until live trading receives explicit owner approval.'),('h1','Required GPT response'),('p','Return: architecture diagram in text; service inventory; provider inventory; real time data flow; API route table; engine input/output table; snapshot lifecycle; freshness and failure states; independent deployment instructions; frontend integration map; known blockers; client decisions; acceptance tests; risks and unresolved assumptions.'),('h1','Evidence rules'),('p','Cite the exact file, route, job, workflow or configuration for every important answer. Label each statement CONFIRMED IN CODE, CONFIRMED IN DEPLOYMENT, UNVERIFIED, MOCKED, DISABLED or RECOMMENDED. Do not assume a key or source file proves a working production feed.'),('h1','Final client decisions'),('p','Finish with decisions required for authoritative service entrypoint, provider entitlements, instruments, freshness targets, snapshot ownership, storage, subscriber permissions, paper/live boundary, seven account mapping, alerts, live risk limits and deployment ownership.')]
def para(t,s): return f'<w:p><w:pPr><w:pStyle w:val="{s}"/></w:pPr><w:r><w:t>{html.escape(t)}</w:t></w:r></w:p>'
body=''.join(para(t,s) for s,t in items)
doc=f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>{body}<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1080" w:right="1080" w:bottom="1080" w:left="1080"/></w:sectPr></w:body></w:document>'
ct='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>'
rels='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>'
with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED) as z:
 z.writestr('[Content_Types].xml',ct); z.writestr('_rels/.rels',rels); z.writestr('word/_rels/document.xml.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"></Relationships>'); z.writestr('word/document.xml',doc)
print(out.resolve())


